import functools
import inspect
import asyncio
from functools import cached_property

def iscoroutinefunction(func):
    try:
        from inspect import iscoroutinefunction as _iscoroutinefunction
        return _iscoroutinefunction(func)
    except ImportError:
        from asyncio import iscoroutinefunction as _iscoroutinefunction
        return _iscoroutinefunction(func)

class MockDependant:
    def __init__(self, call):
        self.call = call

    @cached_property
    def _unwrapped_call(self):
        if self.call is None:
            return self.call
        call = self.call
        while isinstance(call, functools.partial):
            call = call.func
        return inspect.unwrap(call)

    @cached_property
    def is_gen_callable(self):
        if inspect.isgeneratorfunction(self._unwrapped_call):
            return True
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return inspect.isgeneratorfunction(dunder_call)

    @cached_property
    def is_async_gen_callable(self):
        if inspect.isasyncgenfunction(self._unwrapped_call):
            return True
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return inspect.isasyncgenfunction(dunder_call)

    @cached_property
    def is_coroutine_callable(self):
        if inspect.isroutine(self._unwrapped_call):
            return iscoroutinefunction(self._unwrapped_call)
        if inspect.isclass(self._unwrapped_call):
            return False
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return iscoroutinefunction(dunder_call)

def gen():
    yield 1

async def async_gen():
    yield 1

async def async_func():
    return 1

class CallableClass:
    def __call__(self):
        return 1

class AsyncCallableClass:
    async def __call__(self):
        return 1

# Test cases
test_cases = [
    ("gen", gen, True, False, False),
    ("p_gen", functools.partial(gen), True, False, False),
    ("async_gen", async_gen, False, True, False),
    ("p_async_gen", functools.partial(async_gen), False, True, False),
    ("async_func", async_func, False, False, True),
    ("p_async_func", functools.partial(async_func), False, False, True),
    ("cc", CallableClass(), False, False, False),
    ("p_cc", functools.partial(CallableClass()), False, False, False),
    ("acc", AsyncCallableClass(), False, False, True),
    ("p_acc", functools.partial(AsyncCallableClass()), False, False, True),
]

for name, call, expected_gen, expected_async_gen, expected_coro in test_cases:
    dep = MockDependant(call)
    print(f"{name}: gen={dep.is_gen_callable==expected_gen}, async_gen={dep.is_async_gen_callable==expected_async_gen}, coro={dep.is_coroutine_callable==expected_coro}")
